import katex from './vendor/katex/katex.mjs';

const idx = lang => ({zh:0,en:1,ja:2}[lang] ?? 0);
const choose = (values,lang) => values[idx(lang)];
const make = (tag,text,cls) => {const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
export function math(tex,display=false){const n=make(display?'div':'span',undefined,display?'lesson-math':'inline-math');katex.render(tex,n,{displayMode:display,throwOnError:true,trust:false,output:'htmlAndMathml'});return n;}

